BEGIN;
CREATE ROLE authenticated; CREATE ROLE anon; CREATE ROLE service_role;
CREATE SCHEMA auth; CREATE SCHEMA platform_private;
GRANT USAGE ON SCHEMA auth,platform_private TO authenticated;
CREATE TYPE app_role AS ENUM('administrador','gestor','consultor_tecnico','tecnico_agronomo','financeiro','cliente_produtor','aplicador');
CREATE TYPE tipo_visita AS ENUM('vistoria_inicial');
CREATE TYPE categoria_problema_consultor AS ENUM('insetos_praga');
CREATE TYPE nivel_pressao AS ENUM('medio');
CREATE TYPE urgencia_consultor AS ENUM('media');
CREATE TYPE natureza_registro_consultor AS ENUM('ocorrencia','visita');
CREATE TABLE organizations(id uuid PRIMARY KEY,ativo boolean);
CREATE TABLE profiles(id uuid DEFAULT gen_random_uuid(),user_id uuid PRIMARY KEY,organization_id uuid,ativo boolean DEFAULT true,senha_provisoria boolean DEFAULT false,nome text,cliente_id uuid);
CREATE TABLE user_roles(user_id uuid,role app_role);
CREATE TABLE platform_org_admin_invites(user_id uuid,access_operation_status text,access_valid_after timestamptz);
CREATE TABLE clientes(id uuid PRIMARY KEY,organization_id uuid,nome text);
CREATE TABLE fazendas(id uuid PRIMARY KEY,cliente_id uuid,organization_id uuid,nome text);
CREATE TABLE talhoes(id uuid PRIMARY KEY,fazenda_id uuid,organization_id uuid,nome text);
CREATE TABLE culturas(id uuid PRIMARY KEY,nome text);
CREATE TABLE user_clientes(user_id uuid,cliente_id uuid,is_active boolean,revoked_at timestamptz,valid_from timestamptz,valid_until timestamptz,access_level text);
CREATE TABLE registros_consultor(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),client_uuid uuid UNIQUE,cliente_id uuid,fazenda_id uuid,talhao_id uuid,consultor_responsavel uuid,consultor_profile_id uuid,created_by uuid,status text DEFAULT 'rascunho',codigo_visita text,objetivo_visita text,problema_principal text,origem_atendimento text,data_proxima_visita timestamptz,data_vistoria date,created_at timestamptz DEFAULT now(),tipo_visita tipo_visita,urgencia urgencia_consultor,cultura_id uuid,solicitacao_id uuid,version int,pdf_status text,natureza_registro natureza_registro_consultor,safra text,fase_fenologica text,registro_origem_id uuid,categoria_problema categoria_problema_consultor,nivel_pressao nivel_pressao,percentual_area_afetada numeric,localizacao_na_area text,observacoes_tecnicas text,area_hectares numeric,latitude numeric,longitude numeric);
CREATE TABLE portal_solicitacoes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),cliente_id uuid,fazenda_id uuid,talhao_id uuid,created_by uuid,user_id uuid,consultor_atribuido uuid,status text DEFAULT 'pendente',numero_solicitacao text,descricao text,tipo_demanda text,urgencia text,data_prevista_atendimento timestamptz,created_at timestamptz DEFAULT now(),updated_at timestamptz);
CREATE TABLE technical_visit_assignments(registro_consultor_id uuid,user_id uuid,is_active boolean);
CREATE TABLE ordens_servico_onfarm(id uuid,status text,registro_consultor_id uuid);
CREATE TABLE talhao_safras(talhao_id uuid,cultura_id uuid,safra text,status text);
CREATE TABLE solicitacoes_timeline(solicitacao_id uuid,tipo_evento text,descricao text,usuario_id uuid);
GRANT SELECT,INSERT,UPDATE,DELETE ON ALL TABLES IN SCHEMA public TO authenticated;
CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql AS $$ SELECT nullif(current_setting('request.jwt.claim.sub',true),'')::uuid $$;
CREATE FUNCTION auth.jwt() RETURNS jsonb LANGUAGE sql AS $$ SELECT jsonb_build_object('iat',nullif(current_setting('request.jwt.claim.iat',true),'')) $$;
-- Live h15/readiness/roles, reduced invitation DDL; only Auth transport is mocked.
CREATE FUNCTION platform_private.platform_actor_access_ready(p_user uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$
 SELECT EXISTS(SELECT 1 FROM public.profiles p WHERE p.user_id=p_user AND p.ativo IS TRUE AND p.senha_provisoria IS FALSE)
 AND NOT EXISTS(SELECT 1 FROM public.platform_org_admin_invites i WHERE i.user_id=p_user AND (i.access_operation_status='processing' OR (i.access_valid_after IS NOT NULL AND auth.uid()=p_user AND to_timestamp(COALESCE((auth.jwt()->>'iat')::bigint,0))<=i.access_valid_after)));
$$;
CREATE FUNCTION platform_private.h15_actor_organization() RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$
 SELECT p.organization_id FROM public.profiles p JOIN public.organizations o ON o.id=p.organization_id AND o.ativo IS TRUE WHERE p.user_id=auth.uid() AND p.ativo IS TRUE AND platform_private.platform_actor_access_ready(p.user_id);
$$;
CREATE FUNCTION public.h15_actor_organization() RETURNS uuid LANGUAGE sql STABLE SET search_path='' AS $$SELECT platform_private.h15_actor_organization()$$;
CREATE FUNCTION platform_private.has_role(_user_id uuid,_role app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$
 SELECT EXISTS(SELECT 1 FROM public.user_roles r JOIN public.profiles p ON p.user_id=r.user_id WHERE r.user_id=_user_id AND r.role=_role AND p.ativo IS TRUE AND platform_private.platform_actor_access_ready(p.user_id));
$$;
CREATE FUNCTION public.has_role(_user_id uuid,_role app_role) RETURNS boolean LANGUAGE sql STABLE SET search_path='' AS $$SELECT platform_private.has_role(_user_id,_role)$$;
CREATE FUNCTION fn_authz_uid_scope_ok(_uid uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$SELECT auth.uid() IS NULL OR (_uid IS NOT NULL AND _uid=auth.uid()) OR has_role(auth.uid(),'administrador')$$;
CREATE FUNCTION is_visit_responsible(p_user_id uuid,p_registro_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$SELECT EXISTS(SELECT 1 FROM registros_consultor r WHERE r.id=p_registro_id AND (r.consultor_responsavel=p_user_id OR r.created_by=p_user_id OR r.consultor_profile_id IN(SELECT p.id FROM profiles p WHERE p.user_id=p_user_id)))$$;
CREATE FUNCTION is_active_visit_participant(p_user_id uuid,p_registro_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$SELECT EXISTS(SELECT 1 FROM technical_visit_assignments WHERE registro_consultor_id=p_registro_id AND user_id=p_user_id AND is_active=true)$$;
CREATE FUNCTION is_visit_org_manager(p_user_id uuid,p_registro_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$SELECT false$$;
CREATE FUNCTION can_view_technical_visit(p_user_id uuid,p_registro_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$SELECT fn_authz_uid_scope_ok(p_user_id) AND (has_role(p_user_id,'administrador') OR is_visit_responsible(p_user_id,p_registro_id) OR is_active_visit_participant(p_user_id,p_registro_id) OR is_visit_org_manager(p_user_id,p_registro_id))$$;
CREATE FUNCTION can_manage_technical_visit(p_user_id uuid,p_registro_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$SELECT fn_authz_uid_scope_ok(p_user_id) AND (has_role(p_user_id,'administrador') OR is_visit_responsible(p_user_id,p_registro_id) OR is_visit_org_manager(p_user_id,p_registro_id))$$;
CREATE FUNCTION has_active_user_cliente_access(u uuid,c uuid,levels text[]) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$SELECT has_role(u,'administrador') OR EXISTS(SELECT 1 FROM user_clientes WHERE user_id=u AND cliente_id=c AND is_active AND access_level=ANY(levels))$$;
CREATE FUNCTION can_user_access_cliente(c uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$SELECT has_role(auth.uid(),'administrador') OR has_role(auth.uid(),'gestor') OR has_active_user_cliente_access(auth.uid(),c,ARRAY['read','execute','manage'])$$;
CREATE FUNCTION get_cliente_ids_for_user(u uuid) RETURNS uuid[] LANGUAGE sql SECURITY DEFINER SET search_path=public AS $$SELECT ARRAY(SELECT cliente_id FROM user_clientes WHERE user_id=u AND is_active AND revoked_at IS NULL)$$;
ALTER TABLE registros_consultor ENABLE ROW LEVEL SECURITY;
CREATE POLICY audit_a05_tenant_isolation ON registros_consultor AS RESTRICTIVE FOR ALL TO authenticated USING(EXISTS(SELECT 1 FROM clientes c WHERE c.id=registros_consultor.cliente_id AND c.organization_id=h15_actor_organization())) WITH CHECK(EXISTS(SELECT 1 FROM clientes c WHERE c.id=registros_consultor.cliente_id AND c.organization_id=h15_actor_organization()));
CREATE POLICY technical_visit_permissive ON registros_consultor FOR ALL TO authenticated USING(can_view_technical_visit(auth.uid(),id)) WITH CHECK(true);
ALTER TABLE portal_solicitacoes ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Admins can manage all requests" ON portal_solicitacoes FOR ALL TO authenticated USING(platform_private.has_role(auth.uid(),'administrador'));
CREATE POLICY "Creators can view own requests" ON portal_solicitacoes FOR SELECT TO authenticated USING(created_by=auth.uid() OR user_id=auth.uid());
CREATE POLICY "Consultants can view their assigned requests" ON portal_solicitacoes FOR SELECT TO authenticated USING(consultor_atribuido=auth.uid() AND (platform_private.has_role(auth.uid(),'consultor_tecnico') OR platform_private.has_role(auth.uid(),'tecnico_agronomo') OR platform_private.has_role(auth.uid(),'aplicador')));
CREATE POLICY "Portal users can read own requests" ON portal_solicitacoes FOR SELECT TO authenticated USING(cliente_id=ANY(get_cliente_ids_for_user(auth.uid())));
CREATE POLICY "Staff can create requests" ON portal_solicitacoes FOR INSERT TO authenticated WITH CHECK(platform_private.has_role(auth.uid(),'administrador') OR platform_private.has_role(auth.uid(),'gestor') OR platform_private.has_role(auth.uid(),'consultor_tecnico') OR platform_private.has_role(auth.uid(),'tecnico_agronomo'));
CREATE FUNCTION pg_temp.assert_true(label text,result boolean) RETURNS void LANGUAGE plpgsql AS $$BEGIN IF result IS DISTINCT FROM true THEN RAISE EXCEPTION 'FAIL %',label; END IF;RAISE NOTICE 'PASS %',label;END$$;
INSERT INTO organizations VALUES('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',true),('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',true);
INSERT INTO profiles(user_id,organization_id) VALUES('11111111-1111-4111-8111-111111111111','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'),('22222222-2222-4222-8222-222222222222','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'),('33333333-3333-4333-8333-333333333333','bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb'),('44444444-4444-4444-8444-444444444444','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'),('55555555-5555-4555-8555-555555555555',NULL);
INSERT INTO user_roles VALUES('11111111-1111-4111-8111-111111111111','consultor_tecnico'),('22222222-2222-4222-8222-222222222222','administrador'),('33333333-3333-4333-8333-333333333333','administrador'),('44444444-4444-4444-8444-444444444444','financeiro'),('55555555-5555-4555-8555-555555555555','administrador');
INSERT INTO clientes VALUES('aaaaaaaa-0000-4000-8000-000000000001','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','A'),('bbbbbbbb-0000-4000-8000-000000000001','bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb','B');
INSERT INTO fazendas VALUES('aaaaaaaa-0000-4000-8000-000000000002','aaaaaaaa-0000-4000-8000-000000000001','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','A'),('bbbbbbbb-0000-4000-8000-000000000002','bbbbbbbb-0000-4000-8000-000000000001','bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb','B');
INSERT INTO talhoes VALUES('aaaaaaaa-0000-4000-8000-000000000003','aaaaaaaa-0000-4000-8000-000000000002','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','A'),('bbbbbbbb-0000-4000-8000-000000000003','bbbbbbbb-0000-4000-8000-000000000002','bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb','B');
INSERT INTO user_clientes VALUES('11111111-1111-4111-8111-111111111111','aaaaaaaa-0000-4000-8000-000000000001',true,NULL,NULL,NULL,'execute');
INSERT INTO registros_consultor(id,client_uuid,cliente_id,fazenda_id,talhao_id,consultor_responsavel,origem_atendimento) VALUES('aaaaaaaa-0000-4000-8000-000000000004',gen_random_uuid(),'aaaaaaaa-0000-4000-8000-000000000001','aaaaaaaa-0000-4000-8000-000000000002','aaaaaaaa-0000-4000-8000-000000000003','11111111-1111-4111-8111-111111111111','ocorrencia_campo');
INSERT INTO portal_solicitacoes(id,cliente_id,fazenda_id,talhao_id,consultor_atribuido) VALUES('aaaaaaaa-0000-4000-8000-000000000005','aaaaaaaa-0000-4000-8000-000000000001','aaaaaaaa-0000-4000-8000-000000000002','aaaaaaaa-0000-4000-8000-000000000003','11111111-1111-4111-8111-111111111111');
-- BASELINE_RPCS
SELECT set_config('request.jwt.claim.sub','33333333-3333-4333-8333-333333333333',true),set_config('request.jwt.claim.iat',extract(epoch FROM now())::bigint::text,true);
SET LOCAL ROLE authenticated;
SELECT pg_temp.assert_true('baseline direct visit zero',(SELECT count(*) FROM registros_consultor)=0);
SELECT pg_temp.assert_true('baseline helper cross leak',can_view_technical_visit(auth.uid(),'aaaaaaaa-0000-4000-8000-000000000004'));
SELECT pg_temp.assert_true('baseline list cross leak',jsonb_array_length(rpc_listar_atendimentos_tecnicos_v1()->'items')=2);
SELECT pg_temp.assert_true('baseline requests cross leak',(SELECT count(*) FROM portal_solicitacoes)=1);
RESET ROLE;
-- CANDIDATE
SET LOCAL ROLE authenticated;
SELECT pg_temp.assert_true('FSF helper denied',NOT can_view_technical_visit(auth.uid(),'aaaaaaaa-0000-4000-8000-000000000004'));
SELECT pg_temp.assert_true('FSF manage denied',NOT can_manage_technical_visit(auth.uid(),'aaaaaaaa-0000-4000-8000-000000000004'));
SELECT pg_temp.assert_true('FSF list zero',jsonb_array_length(rpc_listar_atendimentos_tecnicos_v1()->'items')=0);
SELECT pg_temp.assert_true('FSF summary zero',(rpc_resumo_atendimentos_tecnicos_v1()->>'todos')::int=0);
SELECT pg_temp.assert_true('FSF requests zero',(SELECT count(*) FROM portal_solicitacoes)=0);
SELECT pg_temp.assert_true('actor forged denied',NOT can_view_technical_visit('11111111-1111-4111-8111-111111111111','aaaaaaaa-0000-4000-8000-000000000004'));
SELECT set_config('request.jwt.claim.sub','11111111-1111-4111-8111-111111111111',true);
SELECT pg_temp.assert_true('responsible view positive',can_view_technical_visit(auth.uid(),'aaaaaaaa-0000-4000-8000-000000000004'));
SELECT pg_temp.assert_true('responsible manage positive',can_manage_technical_visit(auth.uid(),'aaaaaaaa-0000-4000-8000-000000000004'));
SELECT pg_temp.assert_true('responsible list two',jsonb_array_length(rpc_listar_atendimentos_tecnicos_v1()->'items')=2);
SELECT pg_temp.assert_true('responsible summary farms assigned one',(rpc_resumo_atendimentos_tecnicos_v1()->>'fazendas')::int=1);
SELECT pg_temp.assert_true('cross farm ref denied',NOT technical_refs_in_actor_tenant('aaaaaaaa-0000-4000-8000-000000000001','bbbbbbbb-0000-4000-8000-000000000002',NULL));
SELECT pg_temp.assert_true('cross plot ref denied',NOT technical_refs_in_actor_tenant('aaaaaaaa-0000-4000-8000-000000000001','aaaaaaaa-0000-4000-8000-000000000002','bbbbbbbb-0000-4000-8000-000000000003'));
INSERT INTO portal_solicitacoes(cliente_id,created_by) VALUES('aaaaaaaa-0000-4000-8000-000000000001',auth.uid());
SELECT pg_temp.assert_true('own request insert works',(SELECT count(*) FROM portal_solicitacoes)=2);
DO $$ BEGIN
 BEGIN INSERT INTO portal_solicitacoes(cliente_id,created_by) VALUES('bbbbbbbb-0000-4000-8000-000000000001',auth.uid()); RAISE EXCEPTION 'cross insert accepted'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
 PERFORM pg_temp.assert_true('cross request insert denied',true);
END $$;
SELECT set_config('request.jwt.claim.sub','22222222-2222-4222-8222-222222222222',true);
SELECT pg_temp.assert_true('admin A view positive',can_view_technical_visit(auth.uid(),'aaaaaaaa-0000-4000-8000-000000000004'));
UPDATE portal_solicitacoes SET descricao='local update' WHERE id='aaaaaaaa-0000-4000-8000-000000000005';
SELECT pg_temp.assert_true('admin A update works',(SELECT descricao='local update' FROM portal_solicitacoes WHERE id='aaaaaaaa-0000-4000-8000-000000000005'));
SELECT set_config('request.jwt.claim.sub','44444444-4444-4444-8444-444444444444',true);
SELECT pg_temp.assert_true('financial view denied',NOT can_view_technical_visit(auth.uid(),'aaaaaaaa-0000-4000-8000-000000000004'));
SELECT pg_temp.assert_true('financial list forbidden',rpc_listar_atendimentos_tecnicos_v1()->>'error'='forbidden');
SELECT set_config('request.jwt.claim.sub','55555555-5555-4555-8555-555555555555',true);
SELECT pg_temp.assert_true('no org denied',NOT technical_actor_ready(auth.uid()));
SELECT set_config('request.jwt.claim.sub','11111111-1111-4111-8111-111111111111',true),set_config('request.jwt.claim.iat','',true);
SELECT pg_temp.assert_true('missing iat denied',NOT technical_actor_ready(auth.uid()));
SELECT set_config('request.jwt.claim.iat','123',true);
RESET ROLE;
INSERT INTO platform_org_admin_invites VALUES('11111111-1111-4111-8111-111111111111',NULL,now());
SET LOCAL ROLE authenticated;
SELECT pg_temp.assert_true('stale session denied',NOT can_view_technical_visit(auth.uid(),'aaaaaaaa-0000-4000-8000-000000000004'));
RESET ROLE;
DELETE FROM platform_org_admin_invites;
SELECT set_config('request.jwt.claim.iat',extract(epoch FROM now())::bigint::text,true);
UPDATE user_clientes SET revoked_at=now();
SET LOCAL ROLE authenticated;
SELECT pg_temp.assert_true('revoked client denied',NOT can_view_technical_visit(auth.uid(),'aaaaaaaa-0000-4000-8000-000000000004'));
RESET ROLE;
UPDATE user_clientes SET revoked_at=NULL;
UPDATE profiles SET ativo=false WHERE user_id=auth.uid();
SET LOCAL ROLE authenticated;
SELECT pg_temp.assert_true('inactive actor denied',NOT technical_actor_ready(auth.uid()));
RESET ROLE;
UPDATE profiles SET ativo=true WHERE user_id=auth.uid();
-- Farms count remains assigned before the first visit.
DELETE FROM registros_consultor;
SET LOCAL ROLE authenticated;
SELECT pg_temp.assert_true('assigned farm before first visit',(rpc_resumo_atendimentos_tecnicos_v1()->>'fazendas')::int=1);
RESET ROLE;
SET LOCAL ROLE anon;
DO $$ BEGIN BEGIN PERFORM public.rpc_resumo_atendimentos_tecnicos_v1(); RAISE EXCEPTION 'anon accepted';EXCEPTION WHEN insufficient_privilege THEN NULL;END;PERFORM pg_temp.assert_true('anon ACL denied',true);END $$;
RESET ROLE;
ROLLBACK;
